126: function inferYearFromLink(url: string): number | undefined {
127:   const explicitYears = url.match(/(19|20)\d{2}/g) ?? [];
128:   const validYears = explicitYears
129:     .map((yearText) => Number(yearText))
130:     .filter((year) => year >= 1990 && year <= 2035);
131:   if (validYears.length > 0) {
132:     return validYears[validYears.length - 1];
133:   }
134: 
135:   const arxivMatch = url.match(/arxiv\.org\/(?:abs|pdf)\/(\d{2})(\d{2})\./i);
136:   if (arxivMatch) {
137:     return 2000 + Number(arxivMatch[1]);
138:   }
139:   return undefined;
140: }
