279: function rgbToHex([r, g, b]: [number, number, number]): string {
280:   const toHex = (value: number) => value.toString(16).padStart(2, '0');
281:   return `#${toHex(Math.round(r))}${toHex(Math.round(g))}${toHex(Math.round(b))}`;
