284: function blendCategoryColor(categories: ProjectCategory[]): string {
285:   const colors = categories.map((c) => hexToRgb(CATEGORY_BASE_COLORS[c]));
286:   const [r, g, b] = colors.reduce(
287:     (sum, [cr, cg, cb]) => [sum[0] + cr, sum[1] + cg, sum[2] + cb] as [number, number, number],
288:     [0, 0, 0]
289:   );
290:   const divisor = Math.max(colors.length, 1);
291:   return rgbToHex([r / divisor, g / divisor, b / divisor]);
