303: function feColorMatrixLumaTintToDotColor(dotHex: string): string {
304:   const [R, G, B] = hexToRgb(dotHex);
305:   const t = { r: R / 255, g: G / 255, b: B / 255 };
306:   const wr = 0.2126;
307:   const wg = 0.7152;
308:   const wb = 0.0722;
309:   const rows = [
310:     wr * t.r,
311:     wg * t.r,
312:     wb * t.r,
313:     0,
314:     0,
315:     wr * t.g,
316:     wg * t.g,
317:     wb * t.g,
318:     0,
319:     0,
320:     wr * t.b,
321:     wg * t.b,
322:     wb * t.b,
323:     0,
324:     0,
325:     0,
326:     0,
327:     0,
328:     1,
329:     0,
330:   ];
331:   return rows.map((n) => n.toFixed(5)).join(' ');
